update.run:
[ "$ML_REF_KIND" = tag ] || ml_fail "Aucune version publiée de myBrief trouvée : mise à jour impossible."
code=0
bash ./update.sh "${ML_REF#v}" || code=$?
case "$code" in
  0) ;;
  1) ml_fail "Mise à jour non appliquée : myBrief reste dans sa version précédente. Consultez le journal ci-dessus." ;;
  *) ml_fail "La mise à jour a échoué et le retour à la version précédente est incomplet : intervention requise (sauvegarde dans le dossier kit/sauvegardes)." ;;
esac
